-- ============================================================================
-- EduSim IA — Script Inicial de Datos (Seed Obligatorio)
-- Precarga de 10 participantes, perfiles de dominio (D0=0.300), pares validados
-- de Pretest/Postest y Corpus RAG de Desarrollo Web I (MDN Web Docs)
-- ============================================================================

-- 1. Participantes de prueba (EST-001 a EST-005 en Grupo Experimental, EST-006 a EST-010 en Grupo Control)
INSERT INTO participantes (estudiante_hash, condicion_grupo, consentimiento_aceptado, pretest_completado, postest_completado, encuesta_completada)
VALUES
    ('EST-001', 'experimental_adaptativo', FALSE, FALSE, FALSE, FALSE),
    ('EST-002', 'experimental_adaptativo', FALSE, FALSE, FALSE, FALSE),
    ('EST-003', 'experimental_adaptativo', FALSE, FALSE, FALSE, FALSE),
    ('EST-004', 'experimental_adaptativo', FALSE, FALSE, FALSE, FALSE),
    ('EST-005', 'experimental_adaptativo', FALSE, FALSE, FALSE, FALSE),
    ('EST-006', 'control_fijo', FALSE, FALSE, FALSE, FALSE),
    ('EST-007', 'control_fijo', FALSE, FALSE, FALSE, FALSE),
    ('EST-008', 'control_fijo', FALSE, FALSE, FALSE, FALSE),
    ('EST-009', 'control_fijo', FALSE, FALSE, FALSE, FALSE),
    ('EST-010', 'control_fijo', FALSE, FALSE, FALSE, FALSE)
ON CONFLICT (estudiante_hash) DO NOTHING;

-- 2. Inicializar perfil_dominio con D0 = 0.300 en los 8 temas obligatorios
INSERT INTO perfil_dominio (estudiante_hash, tema, dominio_actual)
SELECT p.estudiante_hash, t.tema, 0.300
FROM participantes p
CROSS JOIN (
    VALUES ('DOM-01'), ('DOM-02'), ('DOM-03'), ('JS-04'), ('DAT-05'), ('NET-06'), ('ASY-07'), ('ERR-08')
) AS t(tema)
ON CONFLICT (estudiante_hash, tema) DO NOTHING;

-- 3. Pares Iniciales Validados de Pretest (PRE-01 a PRE-08) y Postest (POST-01 a POST-08)
INSERT INTO banco_preguntas (codigo_item, tipo_uso, tema, nivel_bloom, dificultad, enunciado, opciones, respuesta_correcta, justificacion_pedagogica, pista_guiada, validado_por_docente)
VALUES
    ('PRE-01', 'pretest', 'DOM-01', 'Aplicar', 2,
     'Dado <div id="panel"><p class="nota">A</p><p class="nota">B</p></div>, ¿qué expresión retorna únicamente el primer párrafo con clase "nota"?',
     '{"A": "document.getElementById(\".nota\")", "B": "document.querySelector(\"#panel .nota\")", "C": "document.querySelectorAll(\"#panel .nota\")[1]", "D": "document.getElementsByClassName(\"nota\").first()"}',
     'B',
     'document.querySelector() recibe un selector CSS válido y retorna el primer elemento coincidente dentro del árbol DOM.',
     'Recuerda que querySelector acepta selectores CSS combinados (#id .clase) y devuelve el primer nodo coincidente.',
     TRUE),
    ('PRE-02', 'pretest', 'DOM-02', 'Comprender', 2,
     'Al manejar el envío de un formulario con form.addEventListener("submit", fn), ¿qué método del objeto event evita que la página se recargue?',
     '{"A": "event.stopPropagation()", "B": "event.preventDefault()", "C": "event.cancelBubble()", "D": "form.reset()"}',
     'B',
     'event.preventDefault() cancela la acción predeterminada del navegador asociada al evento submit sin detener su propagación.',
     'Piensa en el método estándar del objeto Event que previene el comportamiento por defecto del navegador.',
     TRUE),
    ('PRE-03', 'pretest', 'DOM-03', 'Aplicar', 3,
     '¿Cuál es la secuencia segura para crear un elemento <li> con texto de usuario e insertarlo en <ul id="lista"> evitando inyección XSS?',
     '{"A": "const li = document.createElement(\"li\"); li.textContent = texto; lista.appendChild(li);", "B": "lista.innerHTML += \"<li>\" + texto + \"</li>\";", "C": "document.write(\"<li>\" + texto + \"</li>\");", "D": "const li = new HTMLElement(\"li\", texto); lista.append(li);"}',
     'A',
     'createElement crea el nodo en memoria, textContent escapa cualquier marca HTML evitando XSS y appendChild lo inserta en el contenedor.',
     'Evita innerHTML cuando insertes texto puro; combina createElement, textContent y appendChild.',
     TRUE),
    ('PRE-04', 'pretest', 'JS-04', 'Analizar', 3,
     '¿Qué imprime en consola el siguiente bloque?\nconst factor = 2;\nconst calcular = (x) => { const factor = 5; return x * factor; };\nconsole.log(calcular(3), factor);',
     '{"A": "6 2", "B": "15 5", "C": "15 2", "D": "Lanza SyntaxError por redeclarar factor"}',
     'C',
     'Por alcance léxico (block scope), la constante factor = 5 sombrea (shadows) a la externa solo dentro de la función flecha (3*5=15), manteniendo factor = 2 fuera de ella.',
     'Analiza el alcance de bloque de const dentro de la función flecha frente al ámbito externo.',
     TRUE),
    ('PRE-05', 'pretest', 'DAT-05', 'Aplicar', 2,
     'Si recibes la cadena const raw = ''{"curso":"Web I","activo":true}'' desde localStorage, ¿cómo accedes a la propiedad curso como objeto JavaScript?',
     '{"A": "JSON.stringify(raw).curso", "B": "JSON.parse(raw).curso", "C": "raw.toObject().curso", "D": "Object.fromJSON(raw).curso"}',
     'B',
     'JSON.parse() deserializa una cadena JSON válida y la convierte en un objeto nativo de JavaScript cuyas propiedades pueden leerse.',
     'Diferencia entre serializar a texto (stringify) y reconstruir el objeto desde texto (parse).',
     TRUE),
    ('PRE-06', 'pretest', 'NET-06', 'Comprender', 3,
     'Al usar fetch("https://api.ejemplo.edu/notas"), la respuesta del servidor es HTTP 404 Not Found. ¿Qué ocurre con la promesa devuelta por fetch?',
     '{"A": "Se rechaza automáticamente entrando al bloque catch", "B": "Se resuelve normalmente, pero response.ok vale false y response.status vale 404", "C": "Retorna null hasta que se llame a response.retry()", "D": "Bloquea el hilo principal del navegador"}',
     'B',
     'fetch() solo rechaza su promesa ante fallos de red o CORS; los códigos HTTP 4xx y 5xx resuelven la promesa con response.ok === false.',
     'Revisa qué valor toma la propiedad booleana response.ok cuando el estado HTTP no está entre 200 y 299.',
     TRUE),
    ('PRE-07', 'pretest', 'ASY-07', 'Aplicar', 3,
     'Dentro de una función async, ¿qué efecto tiene la palabra clave await antes de response.json()?',
     '{"A": "Congela toda la interfaz del navegador hasta recibir los datos", "B": "Pausa la ejecución de esa función async hasta que la promesa se resuelva, sin bloquear el hilo principal", "C": "Convierte cualquier función síncrona en un Web Worker", "D": "Ejecuta response.json() sin necesidad de que la promesa se resuelva"}',
     'B',
     'await suspende de forma no bloqueante la función async actual hasta que la Promesa cambie a estado fulfilled o rejected, liberando el event loop.',
     'Recuerda que async/await es azúcar sintáctico no bloqueante sobre Promesas.',
     TRUE),
    ('PRE-08', 'pretest', 'ERR-08', 'Analizar', 4,
     'En una petición async/await con fetch, ¿cuál es el patrón correcto para capturar tanto fallos de red como respuestas HTTP 500 en un solo bloque catch?',
     '{"A": "Usar try { const r = await fetch(url); if (!r.ok) throw new Error(r.status); } catch (e) { ... }", "B": "Usar únicamente fetch(url).then(r => r.json()) sin verificar r.ok", "C": "Colocar try/catch únicamente alrededor de JSON.stringify()", "D": "Usar window.onerror porque try/catch no funciona con await"}',
     'A',
     'Al verificar if (!r.ok) y lanzar manualmente throw new Error(), forzamos que los estados HTTP de error fluyan hacia el mismo bloque catch que captura fallos de red.',
     'Combina la verificación de !response.ok con throw new Error() dentro de un bloque try...catch.',
     TRUE),
    ('POST-01', 'postest', 'DOM-01', 'Aplicar', 2,
     'En el fragmento <nav id="menu"><a class="item">Inicio</a><a class="item">Cursos</a></nav>, ¿qué instrucción selecciona el primer enlace con clase "item" dentro de #menu?',
     '{"A": "document.querySelector(\"#menu .item\")", "B": "document.getElementById(\"#menu .item\")", "C": "document.querySelectorAll(\".item\").first()", "D": "document.getElementsByName(\"menu.item\")[0]"}',
     'A',
     'document.querySelector("#menu .item") evalúa el selector descendiente CSS y retorna el primer nodo <a> coincidente.',
     'Usa el método del DOM que recibe cualquier selector CSS y devuelve el primer elemento.',
     TRUE),
    ('POST-02', 'postest', 'DOM-02', 'Comprender', 2,
     'Cuando un usuario hace clic en un enlace <a href="/salir"> pero deseas interceptarlo con addEventListener("click", fn) sin navegar a otra ruta, ¿qué debes invocar?',
     '{"A": "event.stopImmediatePropagation()", "B": "event.preventDefault()", "C": "window.stop()", "D": "event.returnValue = true"}',
     'B',
     'event.preventDefault() detiene la navegación predeterminada del elemento <a> permitiendo manejar la acción con JavaScript.',
     'Busca el método estándar de Event que cancela la acción por defecto del elemento HTML.',
     TRUE),
    ('POST-03', 'postest', 'DOM-03', 'Aplicar', 3,
     'Para agregar dinámicamente una tarjeta <article> con un texto seguro proveniente de un input y añadirle la clase "destacado", ¿qué código es el más adecuado?',
     '{"A": "const art = document.createElement(\"article\"); art.classList.add(\"destacado\"); art.textContent = entrada; contenedor.appendChild(art);", "B": "contenedor.innerHTML = \"<article class=destacado>\" + entrada + \"</article>\";", "C": "const art = document.querySelector(\"article\"); art.className.push(\"destacado\");", "D": "document.createNode(\"article\", entrada).appendTo(contenedor);"}',
     'A',
     'createElement junto con classList.add(), textContent y appendChild manipula el DOM de forma estructurada y previene vulnerabilidades XSS.',
     'Utiliza la API estándar del DOM: createElement, classList.add, textContent y appendChild.',
     TRUE),
    ('POST-04', 'postest', 'JS-04', 'Analizar', 3,
     'Analiza el código:\nlet base = 10;\nconst duplicar = (n) => { let base = 4; return n + base; };\nconsole.log(duplicar(6), base);',
     '{"A": "16 10", "B": "10 10", "C": "10 4", "D": "ReferenceError: base is not defined"}',
     'B',
     'Dentro de duplicar, la variable local base = 4 tiene alcance de bloque (6 + 4 = 10), mientras que fuera de la función la variable base conserva su valor 10.',
     'Evalúa primero la suma con la variable local dentro del bloque y luego el valor de la variable externa.',
     TRUE),
    ('POST-05', 'postest', 'DAT-05', 'Aplicar', 2,
     'Tienes el objeto const perfil = { id: "EST-01", nivel: 3 } y necesitas enviarlo como texto en el cuerpo (body) de una petición HTTP. ¿Qué método debes usar?',
     '{"A": "JSON.parse(perfil)", "B": "JSON.stringify(perfil)", "C": "perfil.toJSONText()", "D": "String(perfil)"}',
     'B',
     'JSON.stringify() serializa un objeto o arreglo de JavaScript convirtiéndolo en una cadena de texto con formato JSON estándar.',
     'Para transmitir un objeto por red en formato JSON, debes serializarlo a cadena de texto.',
     TRUE),
    ('POST-06', 'postest', 'NET-06', 'Comprender', 3,
     'Si realizas una petición con fetch() y el servidor responde con código 500 Internal Server Error, ¿cómo puedes detectarlo correctamente en tu código?',
     '{"A": "Comprobando if (!response.ok) o revisando response.status === 500 tras resolver fetch", "B": "Esperando a que fetch devuelva undefined automáticamente", "C": "Verificando si response === false", "D": "No es posible detectar códigos 500 con fetch"}',
     'A',
     'Debido a que fetch resuelve la promesa aun con códigos 500, es indispensable inspeccionar response.ok (que será false) o response.status.',
     'Recuerda qué propiedad booleana de Response indica si el código HTTP estuvo en el rango 200-299.',
     TRUE),
    ('POST-07', 'postest', 'ASY-07', 'Aplicar', 3,
     '¿Qué retorna siempre una función declarada con la palabra clave async en JavaScript, incluso si su cuerpo hace return 42?',
     '{"A": "El número primitivo 42 de forma síncrona", "B": "Una Promesa (Promise) que se resuelve con el valor 42", "C": "Un objeto Callback con estado 42", "D": "Un hilo de ejecución paralelo"}',
     'B',
     'Toda función marcada como async envuelve automáticamente su valor de retorno en una instancia de Promise.',
     'Piensa en el tipo de objeto que devuelve cualquier función async al ser invocada.',
     TRUE),
    ('POST-08', 'postest', 'ERR-08', 'Analizar', 4,
     'Observa el código:\ntry {\n  const res = await fetch(url);\n  if (!res.ok) throw new Error("HTTP " + res.status);\n  return await res.json();\n} catch (err) {\n  console.error(err.message);\n}\nSi el servidor devuelve estado 403, ¿qué se registra en console.error?',
     '{"A": "\"HTTP 403\"", "B": "Nada, porque los errores HTTP no entran al catch aunque se use throw", "C": "undefined", "D": "Un objeto Response completo"}',
     'A',
     'Como res.ok es false para el estado 403, se ejecuta throw new Error("HTTP 403"), transfiriendo el control al bloque catch donde err.message vale "HTTP 403".',
     'Sigue el flujo de ejecución cuando res.ok es false y se lanza el objeto Error con el mensaje personalizado.',
     TRUE)
ON CONFLICT (codigo_item) DO NOTHING;

-- 4. Corpus RAG de Desarrollo Web I (MDN Web Docs resumido por tema)
INSERT INTO corpus_rag (tema, titulo_fuente, contenido)
VALUES
    ('DOM-01', 'MDN: Selección de elementos en el DOM',
     'El método document.getElementById(id) devuelve la referencia al elemento por su atributo id único (sin usar el prefijo #). Por su parte, document.querySelector(selector) acepta cualquier selector CSS válido (como "#panel .nota" o "ul > li.activo") y devuelve el primer Element que coincida, o null si no existe. document.querySelectorAll(selector) devuelve una NodeList estática con todos los elementos coincidentes.'),
    ('DOM-02', 'MDN: Eventos del navegador y Event.preventDefault()',
     'El método target.addEventListener(tipo, listener) registra un manejador de eventos. El objeto event recibido por el callback expone event.target (elemento origen), event.currentTarget (elemento al que se asoció el manejador), event.preventDefault() (que cancela la acción por defecto del navegador, como recargar la página en un evento submit o seguir un enlace <a>) y event.stopPropagation() (que detiene el burbujeo hacia nodos padres).'),
    ('DOM-03', 'MDN: Creación y manipulación segura de nodos DOM',
     'Para modificar dinámicamente el DOM de forma segura: 1) document.createElement(tagName) instancia un nuevo elemento HTML en memoria; 2) element.textContent asigna texto plano escapando etiquetas HTML para prevenir ataques XSS (a diferencia de innerHTML); 3) element.classList.add(), remove() y toggle() gestionan clases CSS sin sobrescribir las existentes; 4) parent.appendChild(node) o parent.append(node) inserta el nodo en el documento.'),
    ('JS-04', 'MDN: Alcance léxico (Scope), let, const y funciones flecha',
     'Las declaraciones let y const tienen alcance de bloque (block scope), limitado al par de llaves {} donde se definen. Si una función interna declara una variable con el mismo nombre que una externa, ocurre sombreado (variable shadowing) sin modificar el valor externo. const impide la reasignación de la referencia, aunque si contiene un objeto sus propiedades internas sí pueden mutar.'),
    ('DAT-05', 'MDN: Objeto global JSON — parse() y stringify()',
     'JSON (JavaScript Object Notation) es un formato de texto para intercambio de datos. JSON.stringify(valor) serializa un objeto o arreglo de JavaScript a una cadena JSON (por ejemplo, para enviarla por HTTP o guardarla en localStorage). JSON.parse(cadena) realiza el proceso inverso: analiza una cadena JSON válida y reconstruye el objeto o arreglo de JavaScript. Si la cadena está mal formada, JSON.parse lanza un SyntaxError.'),
    ('NET-06', 'MDN: Uso de Fetch API y validación de códigos HTTP',
     'La función fetch(url, opciones) inicia una petición HTTP y devuelve una Promise que se resuelve con un objeto Response. Importante: una promesa de fetch() SOLO se rechaza ante un fallo de red o bloqueo CORS; si el servidor responde con HTTP 404 o 500, la promesa se resuelve normalmente con response.ok en false y el código numérico en response.status.'),
    ('ASY-07', 'MDN: Promesas, funciones async y operador await',
     'Una Promise representa un valor eventual y tiene tres estados: pending (pendiente), fulfilled (resuelta) o rejected (rechazada). Toda función declarada con async retorna siempre una Promise. El operador await pausa la ejecución de la función async hasta que la promesa se resuelva y extrae su valor (como en await response.json()), sin bloquear el hilo principal (event loop) del navegador.'),
    ('ERR-08', 'MDN: Manejo de errores con try...catch y throw en código asíncrono',
     'En funciones async/await, el bloque try...catch captura tanto promesas rechazadas como excepciones lanzadas manualmente con throw new Error(mensaje). Dado que fetch() no lanza error en estados HTTP 4xx o 5xx, el patrón robusto consiste en evaluar if (!response.ok) { throw new Error("Error HTTP: " + response.status); } dentro del bloque try para unificar todo el manejo de fallos en el bloque catch.');
